use std::io::{self, Write};

fn main() -> io::Result<()> {
    let mut name = String::new();
    io::stdin().read_line(&mut name)?;
    let name = name.trim();
    // GOOD: bound length and validate content before use in output
    if name.is_empty() || name.chars().count() > 64 {
        eprintln!("invalid input");
        return Ok(());
    }
    println!("Hello {}", name);
    Ok(())
}
